import { MeshBasicNodeMaterial } from 'three/webgpu';
import { Group, Mesh, PlaneGeometry } from 'three/webgpu';

export default function createNode(config, ctx) {
  // root object returned to the scene (position/rotation/scale will be applied by the adapter)
  const root = new Group();

  // geometry: preserve image aspect (512x320 => 1.6:1)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // material placeholder (texture will be set asynchronously)
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // load texture
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      // keep reference for cleanup
      texture = tex;
    })
    .catch(() => {
      // fail silently – material will remain without a map
    });

  // store loaded texture for cleanup
  let texture = null;

  // ----- Cinematic Primitives -------------------------------------------------
  const primitiveInstances = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primSpec of config.cinematicPrimitives) {
      const primitiveFactory = ctx.primitives[primSpec.name];
      if (typeof primitiveFactory === 'function') {
        const instance = primitiveFactory(root, primSpec.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // ----- UserData ------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry
    geometry.dispose();

    // Dispose material
    material.dispose();

    // Dispose texture if it was loaded
    if (texture) {
      texture.dispose();
    }

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst?.cleanup) inst.cleanup();
      if (inst?.timeline && typeof inst.timeline.kill === 'function') {
        inst.timeline.kill();
      }
    }
  };

  // Ensure any pending async work does not keep the node alive after cleanup
  root.userData._cancelTextureLoad = () => {
    // No cancellation mechanism provided by ctx.textureLoader; rely on cleanup later.
  };

  return root;
}
